insert into public.promotions (name,key,is_active,settings) values
('Offerta 2x1','promo_2x1',true,'{"description":"Uno lo paghi. L''altro lo morde chi vuoi.","conditions":"La promo si applica esclusivamente sull''acquisto di una portata principale a scelta (Hamburger Nostrani, Piadine, Wrap o Insalate). Sono categoricamente esclusi dalla promozione stuzzichini, appetizer, fritti, dolci e tutte le bevande. Offerta non cumulabile con altri sconti, utilizzabile per una sola consumazione al tavolo."}'::jsonb),
('Sconto Delivery/Asporto -10%','promo_10',true,'{"description":"Gusta dove vuoi. Risparmia online.","conditions":"Sconto del 10% applicabile a fronte di una spesa minima di 20€. Valido esclusivamente per gli ordini effettuati sul nostro portale ufficiale in modalità Delivery (consegna a domicilio) o Asporto (takeaway).","code":"BUN26","minSpend":20}'::jsonb)
