begin;
delete from public.menu_items;
on conflict (id) do update set label=excluded.label, icon=excluded.icon, position=excluded.position;

on conflict (id) do update set label=excluded.label, color_class=excluded.color_class, icon=excluded.icon;


on conflict (key) do update set name=excluded.name,is_active=excluded.is_active,settings=excluded.settings;
commit;
